// Cleanup: remove watchlist entry for animeId before the run
// so "Add To Watchlist" always starts fresh and won't get a 409.
const baseUrl = pm.environment.get("baseUrl");
const token   = pm.environment.get("token");
const animeId = pm.environment.get("animeId");

if (baseUrl && token && animeId) {
    pm.sendRequest({
        url:    `${baseUrl}/api/watchlist/${animeId}`,
        method: "DELETE",
        header: {
            "Authorization": `Bearer ${token}`,
            "Accept":        "application/json"
        }
    }, function (err, res) {
        // 200/204 = deleted, 404 = wasn't there — both are fine
        console.log("[Cleanup] DELETE watchlist/" + animeId + " →", res ? res.status() : err);
    });

    // Cleanup: remove watched log for animeId before the run
    // so "Log Watched" always starts fresh and won't get a 409.
    pm.sendRequest({
        url:    `${baseUrl}/api/watched/${animeId}`,
        method: "DELETE",
        header: {
            "Authorization": `Bearer ${token}`,
            "Accept":        "application/json"
        }
    }, function (err, res) {
        console.log("[Cleanup] DELETE watched/" + animeId + " →", res ? res.status() : err);
    });
}

