pm.test("Status 200", () => pm.response.to.have.status(200));

const list = pm.response.json();
pm.test("Berisi daftar anime", () => {
    pm.expect(list).to.be.an("array").that.is.not.empty;
});
pm.test("Tiap anime punya field yang lengkap", () => {
    ["id", "title", "year", "studio", "genres", "rating", "episodes",
     "total_episodes", "synopsis", "poster_url", "cast"].forEach(f => {
        pm.expect(list[0]).to.have.property(f);
    });
});

const pick = list[Math.floor(Math.random() * list.length)];
pm.environment.set("animeId", pick.id);

pm.test("Status 200", () => pm.response.to.have.status(200));

const anime = pm.response.json();
pm.test("Berisi anime", () => pm.expect(anime).to.be.an("object").that.is.not.empty);

if (anime.id) {
    pm.environment.set("animeId", anime.id);
}

pm.test("Status 201", () => pm.response.to.have.status(201));

const item = pm.response.json();
pm.test("Anime masuk ke watchlist", () => {
    pm.expect(item.anime_id).to.eql(Number(pm.environment.get("animeId")));
    pm.expect(item.anime).to.have.property("title");
});

pm.test("Status 200", () => pm.response.to.have.status(200));
pm.test("Progress tersimpan", () => {
    const p = pm.response.json();
    pm.expect(p.status).to.eql("watching");
    pm.expect(p.current_episode).to.eql(3);
});

pm.test("Status 201", () => pm.response.to.have.status(201));

const entry = pm.response.json();
pm.test("Review tersimpan", () => {
    pm.expect(entry.rating).to.eql(5);
    pm.expect(entry.review).to.eql("Seru Banget");
    pm.expect(entry.anime_id).to.eql(Number(pm.environment.get("animeId")));
});

pm.test("Status 200", () => pm.response.to.have.status(200));

const recs = pm.response.json();
pm.test("Berupa daftar rekomendasi", () => {
    pm.expect(recs).to.be.an("array").that.is.not.empty;
    recs.forEach(r => {
        pm.expect(r).to.have.property("anime");
        pm.expect(r).to.have.property("score");
        pm.expect(r.reason).to.be.a("string");
    });
});
pm.test("Anime yang sudah dicatat tidak direkomendasikan", () => {
    const seen = Number(pm.environment.get("animeId"));
    pm.expect(recs.map(r => r.anime.id)).to.not.include(seen);
});
pm.test("Diurutkan dari skor tertinggi", () => {
    const scores = recs.map(r => r.score);
    pm.expect(scores).to.eql([...scores].sort((a, b) => b - a));
});
